<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import {NButton,NInput,NModal,NSelect} from 'naive-ui'
import {money,statuses,type Account} from '../api/funds'
import {membersApi,type Member,type MemberDetail,type Claim} from '../api/memberClaims'
import ClaimEditor from '../components/ClaimEditor.vue'
import RepaymentEditor from '../components/RepaymentEditor.vue'
import TransfersView from './TransfersView.vue'
const props=defineProps<{accounts:Account[];trusted:boolean;active:boolean;focusMember?:string;focusClaim?:string}>()
const emit=defineEmits<{changed:[];notice:[string];member:[string,string]}>()
const members=ref<Member[]>([]),selected=ref<string|null>(null),detail=ref<MemberDetail|null>(null),error=ref(''),busy=ref(false),showClaim=ref(false),showRepayment=ref(false),edit=ref(false),editingId=ref(''),name=ref(''),note=ref(''),confirming=ref<Claim|null>(null),amount=ref(''),reason=ref(''),confirmation=ref<{claim:Claim;amount:string;reason:string}|null>(null)
async function load(){try{members.value=await membersApi.list();const id=selected.value;if(id){const result=await membersApi.detail(id);if(selected.value===id)detail.value=result}}catch(e){error.value=(e as Error).message}}
async function select(id:string|null){selected.value=id;detail.value=null;error.value='';showClaim.value=false;showRepayment.value=false;confirming.value=null;confirmation.value=null;if(!id)return;try{const result=await membersApi.detail(id);if(selected.value===id)detail.value=result}catch(e){error.value=(e as Error).message}}
async function focus(){if(props.focusMember){await select(props.focusMember);if(props.focusClaim){const claim=detail.value?.claims.find(c=>c.id===props.focusClaim);if(claim?.status==='pending'&&props.trusted)openConfirm(claim)}}}
function editMember(member?:Member){editingId.value=member?.id||'';name.value=member?.name||'';note.value=member?.note||'';edit.value=true;error.value=''}
async function saveMember(){busy.value=true;try{const m=editingId.value?await membersApi.update(editingId.value,{name:name.value,note:note.value}):await membersApi.create({name:name.value,note:note.value});edit.value=false;selected.value=m.id;await load();emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function openBusiness(memberId:string,claimId:string){if(memberId!==detail.value?.member.id){emit('member',memberId,claimId);return}const c=detail.value?.claims.find(c=>c.id===claimId);if(c?.status==='pending'&&props.trusted)openConfirm(c)}
function closeConfirm(){if(!confirmation.value)confirming.value=null}
function openConfirm(claim:Claim){confirming.value=claim;amount.value=money(claim.declared_minor);reason.value='';confirmation.value=null;error.value=''}
async function confirm(){if(!confirming.value||busy.value)return;busy.value=true;confirmation.value ||= {claim:confirming.value,amount:amount.value,reason:reason.value};try{const input=confirmation.value;await membersApi.confirm(input.claim,input.amount,input.reason);confirming.value=null;confirmation.value=null;await saved()}catch(e){error.value=(e as Error).message+'。结果不确定时请先查询已存记录；重试保留原确认内容和版本。'}finally{busy.value=false}}
async function reject(){if(!confirming.value||!reason.value.trim()||confirmation.value)return;busy.value=true;try{await membersApi.reject(confirming.value,reason.value);confirming.value=null;await saved()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function saved(){await load();emit('changed');emit('notice','成员记录已更新')}
watch(()=>[props.focusMember,props.focusClaim],focus)
onMounted(async()=>{try{await load();await focus()}catch(e){error.value=(e as Error).message}})
</script>
<template><h2>成员垫付与偿还</h2><div class="actions"><NSelect :value="selected" :options="members.map(m=>({label:m.name,value:m.id}))" placeholder="选择成员" style="min-width:220px" @update:value="select"/><NButton @click="load">刷新</NButton><NButton v-if="trusted" @click="editMember()">新增成员</NButton></div><p v-if="error" class="error">{{error}}</p><p v-if="!members.length" class="muted">暂无成员。受信任用户可新增成员后代录垫付。</p><template v-if="detail"><h3>{{detail.member.name}}</h3><p>{{detail.member.note||'暂无备注'}}</p><div class="actions" v-if="trusted"><NButton @click="editMember(detail.member)">编辑成员</NButton><NButton @click="showClaim=true">代录垫付</NButton><NButton @click="showRepayment=true">记录偿还</NButton></div><div class="table-wrap"><table><thead><tr><th>未确认申报</th><th>有效确认金额</th><th>有效偿还</th><th>垫付未结</th><th>其他往来</th><th>全部往来余额</th></tr></thead><tbody><tr><td>{{money(detail.pending_minor)}}</td><td>{{money(detail.confirmed_minor)}}</td><td>{{money(detail.repaid_minor)}}</td><td>{{money(detail.outstanding_minor)}}</td><td>{{money(detail.other_movements_minor)}}</td><td>{{money(detail.ledger_balance_minor)}}</td></tr></tbody></table></div><p class="muted">全部往来余额包含逐笔垫付未结和其他往来。普通划转不会自动匹配垫付。</p><h3>逐笔垫付及待确认申报</h3><div class="table-wrap"><table><thead><tr><th>日期 / 编号</th><th>去向 / 依据</th><th>申报</th><th>确认</th><th>已偿还</th><th>未结</th><th>状态</th><th></th></tr></thead><tbody><tr v-for="c in detail.claims" :key="c.id"><td>{{c.transfer.effective_date}}<br>{{c.id}}</td><td>{{c.transfer.destination_account_name}}<br>{{c.basis}}<br>{{c.confirmation_reason}}</td><td>{{money(c.declared_minor)}}</td><td>{{c.confirmed_minor===null?'待确认':money(c.confirmed_minor)}}</td><td>{{money(c.repaid_minor)}}</td><td>{{money(c.outstanding_minor)}}</td><td>{{statuses[c.status]}}</td><td><NButton v-if="trusted&&c.status==='pending'" @click="openConfirm(c)">确认金额 / 拒绝</NButton></td></tr></tbody></table></div><h3>偿还匹配历史</h3><p v-if="!detail.repayments.length" class="muted">暂无偿还记录。</p><div v-for="r in detail.repayments" :key="r.id"><p>{{r.transfer.effective_date}}，¥{{money(r.amount_minor)}}，{{statuses[r.status]}}（{{r.id}}）</p><p>{{r.basis}}；{{r.effective?'匹配有效':'匹配已失效，历史保留'}}；冲销流水：{{r.reversal_id||'无'}}</p><ul><li v-for="a in r.allocations" :key="a.claim_id">垫付 {{a.claim_id}}：¥{{money(a.amount_minor)}}</li></ul></div><h3>其他往来追溯</h3><p v-if="!detail.other_transfers.length" class="muted">暂无其他正式往来。</p><p v-for="t in detail.other_transfers" :key="t.id">{{t.effective_date}}，{{t.source_account_name}} → {{t.destination_account_name}}，¥{{money(t.amount_minor)}}（{{t.id}}）</p><h3>关联资金详情与冲销</h3><p class="muted">垫付已有有效偿还时，须先冲销关联偿还后再冲销垫付；服务端会拒绝不符合条件的操作。</p><TransfersView :items="[...detail.claims.map(c=>c.transfer),...detail.repayments.map(r=>r.transfer),...detail.other_transfers]" :accounts="accounts" :approvals="false" :trusted="trusted" @changed="saved" @notice="emit('notice',$event)" @member="openBusiness"/><ClaimEditor :key="detail.member.id" :show="active&&showClaim" :member="detail.member" :accounts="accounts" @close="showClaim=false" @saved="saved"/><RepaymentEditor :key="detail.member.id" :show="active&&showRepayment" :member="detail.member" :accounts="accounts" :claims="detail.claims" @close="showRepayment=false" @saved="saved"/></template><NModal :show="active&&edit" preset="card" title="成员资料" class="dialog" @close="edit=false"><label>姓名<NInput v-model:value="name"/></label><label>备注<NInput v-model:value="note"/></label><p v-if="error" class="error">{{error}}</p><NButton :loading="busy" @click="saveMember">保存成员</NButton></NModal><NModal :show="active&&!!confirming" preset="card" title="确认垫付金额" class="dialog" @close="closeConfirm"><template v-if="confirming"><p>申报 ¥{{money(confirming.declared_minor)}}，{{confirming.basis}}</p><label>确认金额（元）<NInput v-model:value="amount" :disabled="!!confirmation||busy"/></label><label>部分确认或拒绝原因<NInput v-model:value="reason" :disabled="!!confirmation||busy"/></label><p v-if="error" class="error">{{error}}</p><div class="actions"><NButton :loading="busy" :disabled="!!confirmation" @click="reject">拒绝申报</NButton><NButton :loading="busy" @click="confirm">{{confirmation?'重试原确认请求':'确认并过账'}}</NButton><NButton v-if="confirmation" :disabled="busy" @click="confirmation=null;confirming=null;load()">查询已存记录</NButton></div></template></NModal></template>
